[meta]
name = The Vigil Chapel
ambient = 0.34 0.38 0.5
fog = 0.05 0.06 0.1
fog_range = 12 60
torch = 7 0.8 0.86 1.0
start = 8 20 -90
default = n
edge_top = 16
edge_tex = moonstone
entity_floor = auto

[legend]
// Walls of moonstone, rising past the nave's vault.
# = wall tex=moonstone top=16 cap=silver_slate
// The vestibule inside the door, under a low vault.
v = floor tex=moon_paving h=0 ceil=5 ceil_tex=silver_slate side=moonstone dark=0.25
// The nave, tall and dim, and the lower aisles either side of its pillars.
n = floor tex=moon_paving h=0 ceil=12 ceil_tex=silver_slate side=moonstone dark=0.2
a = floor tex=moon_paving h=0 ceil=7 ceil_tex=silver_slate side=moonstone dark=0.3
// The step up to the chancel, and the chancel itself, floored in moon-glass.
s = floor tex=moon_paving h=0.5 ceil=12.5 ceil_tex=silver_slate side=moonstone dark=0.15
c = floor tex=moon_glass h=1 ceil=13 ceil_tex=silver_slate side=moonstone dark=0.1

